"""Realistic warehouse simulation for emergent AGV coalitions.

This module is intentionally more physical than the small verification gates:

* loads appear over time at random border stations of a square warehouse;
* each load has weight 1..10 and each robot contributes one unit of capacity;
* robots communicate only inside ``R_com`` and sense obstacles inside ``R_sensing``;
* robots follow unicycle/differential-drive limits induced by wheel motors;
* recruitment is generated by Smith dynamics with effective occupancy estimates;
* transport starts only when enough robots are physically close to the load;
* formations are kept as moving slots around each load while obstacles are avoided.

The simulator remains a kinematic research prototype. It is meant to start the TFM
campaign and expose falsifiable metrics before moving the same controller to a richer
physics engine.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any

import numpy as np
from numpy.typing import NDArray
from scipy.optimize import linear_sum_assignment


Array = NDArray[np.float64]

LOAD_NOT_SPAWNED = -1
LOAD_RECRUITING = 0
LOAD_TRANSPORT = 1
LOAD_DELIVERED = 2
LOAD_CANCELED = 3

