POLICY_SMITH_QR_CLEARING_GUARD = "smith_qr_clearing_guard"
POLICY_SMITH_QR_FULL = "smith_qr_full"
POLICY_SMITH = POLICY_SMITH_FULL
POLICY_GREEDY_NEAREST = "classic_greedy_nearest"
POLICY_CENTRALIZED_MINCOST = "classic_centralized_mincost"
POLICY_CENTRALIZED_LIMITED_COMM = "classic_centralized_limited_comm"
POLICY_AUCTION_CBBA = "classic_auction_cbba"
POLICY_PROXY_TOKEN_PASSING = "proxy_token_passing"
POLICY_PROXY_ROLLING_HORIZON = "proxy_rolling_horizon"
POLICY_PROXY_PIBT = "proxy_pibt_priority"
POLICY_TOKEN_PASSING = POLICY_PROXY_TOKEN_PASSING
POLICY_ROLLING_HORIZON = POLICY_PROXY_ROLLING_HORIZON
POLICY_PIBT = POLICY_PROXY_PIBT
POLICY_ORACLE_CLAIRVOYANT = "oracle_clairvoyant"
POLICY_RESPONSE_THRESHOLD = "response_threshold"
POLICY_RANDOM_FEASIBLE = "random_feasible"
