@dataclass(slots=True)
class WarehouseObstacle:
    """Circular obstacle used by the local sensing layer."""

    center: Array
    radius: float = 0.55
    influence_radius: float = 2.0

    def __post_init__(self) -> None:
        self.center = np.asarray(self.center, dtype=float)
        if self.center.shape != (2,):
            msg = "Obstacle center must be a 2D vector."
            raise ValueError(msg)
        if self.radius <= 0.0 or self.influence_radius <= self.radius:
            msg = "Obstacle radii must satisfy 0 < radius < influence_radius."
            raise ValueError(msg)


@dataclass(slots=True)
class WarehouseLoad:
    """Dynamic warehouse transport request."""

    identifier: str
    source: Array
    target: Array
    weight: int
    spawn_time: float
    reward: float
    max_price: float
    position: Array = field(init=False)
    price: float = 0.0
    status: int = LOAD_NOT_SPAWNED
    coalition_time: float = np.nan
    delivered_time: float = np.nan
    cancel_time: float = np.nan
    hold_count: int = 0
    break_count: int = 0
    coalition_breaks: int = 0

    def __post_init__(self) -> None:
        self.source = np.asarray(self.source, dtype=float)
        self.target = np.asarray(self.target, dtype=float)
        if self.source.shape != (2,) or self.target.shape != (2,):
            msg = "Load source and target must be 2D vectors."
            raise ValueError(msg)
        if not 1 <= int(self.weight) <= 10:
            msg = "Load weight must be an integer in [1, 10]."
            raise ValueError(msg)
        self.weight = int(self.weight)
        self.position = self.source.copy()


